script:
# Server Script — "Chatwoot API"
# Script Type: API | API Method: chatwoot_api | Allow Guest: Yes (see below)
#
# Chatwoot API: the one door from Helpdesk to Chatwoot.
#   HTTP:     POST /api/method/chatwoot_api  {action, payload}            (System Manager only)
#   Internal: run_script("Chatwoot API", action=..., payload=...) from other server scripts;
#             the result comes back in frappe.flags.chatwoot_result.
# Every Chatwoot request writes one Chatwoot Sync Log row, success or failure.
# The API token is read here only (Password field) and never returned, logged or sent to the browser.
# The webhook key (Chatwoot Settings.webhook_key) is redacted to *** in every logged request/response.
#
# Why Allow Guest = Yes: the Chatwoot webhook ("Chatwoot Webhook", chatwoot_webhook_<key>) runs as Guest and
# run_script() refuses a guest call into an allow_guest=0 script. Guest is still refused here unless ALL hold:
#   - the current HTTP request is /api/method/chatwoot_webhook_<webhook_key> (form_dict.cmd; inside the webhook),
#   - the webhook passed the same key again (webhook_key kwarg, compared with Chatwoot Settings),
#   - the action is get_conversation, list_labeled_conversations or add_private_note.
# A direct HTTP call to /api/method/chatwoot_api still needs a System Manager.
# Any other non-admin caller (the HD Ticket scripts, running as the agent who saved the ticket) must pass
# internal_key = Chatwoot Settings.internal_key, which only server scripts can read; this also closes
# /api/v2/method/chatwoot_api, where cmd is empty.
#
# Actions: test_connection, list_agents, find_contact_by_phone, get_conversation, list_labeled_conversations,
#          add_private_note, set_conversation_label, send_customer_message, ensure_conversation, setup_webhook, retry


def n9(phone):
	# The join key: digits only, no leading zeros, 252 prefix, compared on the last 9 digits.
	d = "".join([c for c in str(phone or "") if c.isdigit()]).lstrip("0")
	if not d:
		return ""
	if not d.startswith("252"):
		d = "252" + d
	return d[-9:]


def cw(ctx, method, path, body):
	# One Chatwoot request + its Sync Log row. Returns {ok, status, data, error, log}.
	url = ctx["base"] + "/api/v1/accounts/" + str(ctx["account"]) + path
	headers = {"api_access_token": ctx["token"], "Content-Type": "application/json", "Accept": "application/json"}
	res = {"ok": False, "status": 0, "data": None, "error": None, "log": None}
	started = frappe.utils.now_datetime()
	# No timeout possible: make_request() here takes no timeout argument (tested), so a hung Chatwoot can delay a save.
	try:
		if method == "GET":
			res["data"] = frappe.make_get_request(url, headers=headers)
		elif method == "PATCH":
			res["data"] = frappe.make_patch_request(url, headers=headers, data=json.dumps(body))
		elif method == "DELETE":
			res["data"] = frappe.make_delete_request(url, headers=headers)
		else:
			res["data"] = frappe.make_post_request(url, headers=headers, data=json.dumps(body))
		res["ok"] = True
		res["status"] = 200
	except Exception as e:
		code = 0
		try:
			code = e.response.status_code
		except Exception:
			code = 0
		res["status"] = code
		res["error"] = str(e)[:1000]
		# frappe.make_*_request writes its own Error Log on failure, with the local variables (our headers = the
		# token). Mask every secret in Error Log rows of the last 5 minutes. SELECT + set_value only; never printed.
		since = frappe.utils.add_to_date(frappe.utils.now_datetime(), minutes=-5)
		for sec in [ctx["token"]] + (ctx.get("secrets") or []):
			if sec and len(str(sec)) >= 16:
				rows = frappe.db.sql("select name, method, error from `tabError Log` where creation > %(t)s and "
					"(error like %(p)s or method like %(p)s)", {"t": since, "p": "%" + str(sec) + "%"}, as_dict=True)
				for row in rows:
					err = row.error or ""
					meth = row.method or ""
					for other in [ctx["token"]] + (ctx.get("secrets") or []):
						if other and len(str(other)) >= 16:
							err = err.replace(str(other), "***")
							meth = meth.replace(str(other), "***")
					frappe.db.set_value("Error Log", row.name, {"error": err, "method": meth}, update_modified=False)
	took = int((frappe.utils.now_datetime() - started).total_seconds() * 1000)
	text = res["data"] if isinstance(res["data"], str) else json.dumps(res["data"], default=str)
	reqtext = json.dumps({"action": ctx["action"], "payload": ctx["payload"], "body": body}, indent=1, default=str)
	# Redaction: known secrets, then whatever follows "chatwoot_webhook_" / "chatwoot_webhook?key=" in a URL
	# (also old keys Chatwoot still has).
	clean = []
	for t in [reqtext, text or "", res["error"] or ""]:
		for sec in ctx.get("secrets") or []:
			if sec:
				t = t.replace(sec, "***")
		for marker in ["chatwoot_webhook_", "chatwoot_webhook?key="]:
			parts = t.split(marker)
			out = parts[0]
			for p in parts[1:]:
				i = 0
				while i < len(p) and (p[i].isalnum() or p[i] in "-_%"):
					i = i + 1
				out = out + marker + "***" + p[i:]
			t = out
		clean.append(t)
	reqtext = clean[0]
	text = clean[1]
	res["error"] = clean[2] or None
	log = frappe.get_doc({
		"doctype": "Chatwoot Sync Log",
		"direction": "Outbound",
		"event": ctx["action"],
		"status": "Success" if res["ok"] else "Failed",
		"http_status": res["status"],
		"reference_ticket": ctx.get("ticket"),
		"chatwoot_conversation_id": ctx.get("conversation_id"),
		"retry_of": ctx.get("retry_of"),
		"duration_ms": took,
		"method": method,
		"path": path,
		"request": reqtext,
		"response": (text or "")[:20000],
		"error": res["error"],
	}).insert(ignore_permissions=True)
	res["log"] = log.name
	return res


def intl(phone):
	# Full international digits for WhatsApp: Somali numbers -> 252XXXXXXXXX; other countries when they carry a
	# country code (+44 7..., 0044..., or 11-15 digits not starting with 0, e.g. 447...). "" when unusable.
	# 2026-10-19 (user-approved): explicit +/00 numbers accept the full E.164 range, 8-15 digits, same as
	# the HD Ticket Caller Validation rule. Bare 9 digits stay Somali.
	raw = str(phone or "").strip()
	d = "".join([c for c in raw if c.isdigit()])
	if d.startswith("00"):
		d = d[2:]
	if len(d) == 9 and not d.startswith("0"):
		return "252" + d
	if len(d) == 10 and d.startswith("0"):
		return "252" + d[1:]
	if len(d) == 12 and d.startswith("252") and d[3] != "0":
		return d
	if (raw.startswith("+") or raw.startswith("00") or len(d) >= 11) and 8 <= len(d) <= 15 and not d.startswith("252") and not d.startswith("0"):
		return d
	return ""


def strict_phone(phone):
	# A real Somali mobile only: 9 digits, 0 + 9 digits, or 252 + 9 digits (optionally with +/spaces/dashes).
	d = "".join([c for c in str(phone or "") if c.isdigit()])
	if len(d) == 12 and d.startswith("252"):
		d = d[3:]
	elif len(d) == 10 and d.startswith("0"):
		d = d[1:]
	return len(d) == 9 and not d.startswith("0")


def skip_log(action, payload, reason):
	return frappe.get_doc({
		"doctype": "Chatwoot Sync Log",
		"direction": "Outbound",
		"event": action,
		"status": "Skipped",
		"reference_ticket": payload.get("ticket"),
		"chatwoot_conversation_id": payload.get("conversation_id"),
		"request": json.dumps({"action": action, "payload": payload}, indent=1, default=str),
		"error": reason,
	}).insert(ignore_permissions=True).name


args = frappe.form_dict
action = args.get("action") or ""
payload = args.get("payload") or {}
if isinstance(payload, str):
	payload = json.loads(payload) if payload.strip() else {}

user = frappe.session.user
admin = user == "Administrator" or bool(frappe.get_all(
	"Has Role", filters={"parent": user, "parenttype": "User", "role": "System Manager"}, pluck="role"))
agent = admin or bool(frappe.get_all(
	"Has Role", filters={"parent": user, "parenttype": "User", "role": ["in", ["Agent", "Agent Manager"]]}, pluck="role"))
# Called over HTTP (not through run_script from another server script): admins only.
# frappe.request does not exist in safe_exec. form_dict.cmd is the /api/method/<cmd> that is really running
# (a body "cmd" re-routes the request to that method, so it cannot point at another script) and it stays
# set inside run_script(). /api/v2/method/... leaves cmd empty: see the Guest rule below.
cmd = str(args.get("cmd") or "")
external = cmd == "chatwoot_api"
s = frappe.get_doc("Chatwoot Settings")
if user == "Guest":
	# Only from inside the webhook (after its key check), only the read/note actions, and only with the key again.
	wkey = s.get_password("webhook_key", raise_exception=False) or ""
	given = str(args.get("webhook_key") or "")
	if (len(wkey) < 32 or cmd != "chatwoot_webhook_" + wkey or given != wkey
			or action not in ["get_conversation", "list_labeled_conversations", "add_private_note"]):
		frappe.throw("Not permitted", frappe.PermissionError)
elif not admin:
	ikey = s.get_password("internal_key", raise_exception=False) or ""
	if external or not agent or len(ikey) < 32 or str(args.get("internal_key") or "") != ikey:
		frappe.throw("Not permitted", frappe.PermissionError)
if action == "setup_webhook" and not admin:
	frappe.throw("Not permitted", frappe.PermissionError)

retry_of = None
if action == "retry":
	if not admin:
		frappe.throw("Not permitted", frappe.PermissionError)
	src = frappe.get_doc("Chatwoot Sync Log", payload.get("log"))
	if src.direction != "Outbound" or src.status not in ["Failed", "Skipped"]:
		frappe.throw("Only failed or skipped outbound rows can be retried.")
	req = json.loads(src.request or "{}")
	action = req.get("action") or ""
	payload = req.get("payload") or {}
	retry_of = src.name

# Test mode: while Chatwoot Settings "Test numbers" has numbers, customer messages go only to them.
test_keys = []
for x in (s.test_numbers or "").replace(",", "\n").split("\n"):
	if x.strip():
		test_keys.append(n9(x))

result = None
if action not in ["test_connection", "list_agents", "find_contact_by_phone", "get_conversation", "add_private_note",
		"set_conversation_label", "send_customer_message", "list_labeled_conversations", "setup_webhook", "ensure_conversation",
		"send_agent_message"]:
	frappe.throw("Unknown action: " + str(action))

if not s.enabled and action not in ["test_connection", "list_agents", "setup_webhook"]:
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Integration is disabled in Chatwoot Settings")}
elif action in ["send_customer_message", "send_agent_message"] and s.whatsapp_paused:
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "WhatsApp messages are paused (Kanban switch)")}
elif action == "send_agent_message" and not s.notify_agents:
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Agent notifications are off in Chatwoot Settings")}
elif action == "send_agent_message" and not intl(payload.get("phone")):
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Agent has no valid phone (User mobile / Employee cell / User phone)")}
elif action == "send_agent_message" and frappe.db.count("Chatwoot Sync Log", {"event": ["in", ["send_customer_message", "send_agent_message"]],
		"status": "Success", "creation": [">", frappe.utils.add_to_date(frappe.utils.now_datetime(), seconds=-60)]}) >= (s.max_messages_per_minute or 20):
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Rate limit: too many messages this minute (retry later)")}
elif action == "send_customer_message" and not s.send_customer_messages:
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Customer-facing messages are off in Chatwoot Settings")}
elif action == "send_customer_message" and payload.get("ticket") and frappe.db.get_value("HD Ticket", payload.get("ticket"), "chatwoot_opted_out"):
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Customer opted out (JOOJI)")}
elif action == "send_customer_message" and not intl(payload.get("phone")):
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "No valid phone for this customer")}
elif action == "send_customer_message" and test_keys and n9(payload.get("phone")) not in test_keys:
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Test mode: number is not in Test numbers")}
elif action == "send_customer_message" and frappe.db.count("Chatwoot Sync Log", {"event": "send_customer_message", "status": "Success",
		"creation": [">", frappe.utils.add_to_date(frappe.utils.now_datetime(), seconds=-60)]}) >= (s.max_messages_per_minute or 20):
	result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Rate limit: too many customer messages this minute (retry later)")}
else:
	token = s.get_password("api_token", raise_exception=False)
	if not token or not s.base_url or not s.account_id:
		result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Base URL, Account ID or API token is missing")}
	else:
		ctx = {"base": s.base_url.rstrip("/"), "account": s.account_id, "token": token, "action": action,
			"payload": payload, "ticket": payload.get("ticket"), "conversation_id": payload.get("conversation_id"),
			"retry_of": retry_of, "secrets": [token, s.get_password("webhook_key", raise_exception=False),
				s.get_password("internal_key", raise_exception=False)]}

		if action == "test_connection":
			r = cw(ctx, "GET", "/inboxes", None)
			boxes = []
			if r["ok"]:
				boxes = [{"id": b.get("id"), "name": b.get("name"), "type": b.get("channel_type")} for b in (r["data"] or {}).get("payload") or []]
			result = {"ok": r["ok"], "status": r["status"], "error": r["error"], "inboxes": boxes, "log": r["log"]}

		elif action == "list_agents":
			r = cw(ctx, "GET", "/agents", None)
			rows = []
			if r["ok"]:
				hd = frappe.get_all("HD Agent", fields=["name", "user", "agent_name"])
				for a in r["data"] or []:
					email = (a.get("email") or "").lower()
					match = None
					for h in hd:
						if (h.user or h.name or "").lower() == email:
							match = h.name
					rows.append({"chatwoot_agent_id": a.get("id"), "chatwoot_name": a.get("name"), "chatwoot_email": a.get("email"),
						"hd_agent": match})
			result = {"ok": r["ok"], "status": r["status"], "error": r["error"], "agents": rows, "log": r["log"]}

		elif action == "find_contact_by_phone":
			key = n9(payload.get("phone"))
			if len(key) != 9:
				frappe.throw("Phone number must have at least 9 digits")
			found = []
			verified = False
			cached = payload.get("contact_id")
			if cached:
				# Cached IDs are verified before use; a 404 or a different phone means search again.
				r = cw(ctx, "GET", "/contacts/" + str(int(cached)), None)
				c = ((r["data"] or {}).get("payload") or {}) if r["ok"] else {}
				if r["ok"] and n9(c.get("phone_number")) == key:
					found = [{"id": c.get("id"), "name": c.get("name"), "phone_number": c.get("phone_number")}]
					verified = True
			if not found:
				r = cw(ctx, "GET", "/contacts/search?include_contacts=true&q=" + key, None)
				for c in ((r["data"] or {}).get("payload") or []) if r["ok"] else []:
					if n9(c.get("phone_number")) == key:
						found.append({"id": c.get("id"), "name": c.get("name"), "phone_number": c.get("phone_number")})
			result = {"ok": r["ok"], "key": key, "cache_verified": verified, "contacts": found, "log": r["log"]}

		elif action == "get_conversation":
			cid = int(payload.get("conversation_id") or 0)
			r = cw(ctx, "GET", "/conversations/" + str(cid), None)
			out = {"ok": r["ok"], "status": r["status"], "error": r["error"], "conversation": r["data"] if r["ok"] else None, "log": r["log"]}
			if r["ok"] and payload.get("with_messages"):
				m = cw(ctx, "GET", "/conversations/" + str(cid) + "/messages", None)
				out["messages"] = ((m["data"] or {}).get("payload") or []) if m["ok"] else []
			result = out

		elif action == "add_private_note":
			cid = int(payload.get("conversation_id") or 0)
			content = str(payload.get("content") or "").strip()
			if not cid or not content:
				frappe.throw("conversation_id and content are required")
			# Always private: this door never sends a customer-facing message.
			r = cw(ctx, "POST", "/conversations/" + str(cid) + "/messages",
				{"content": content, "message_type": "outgoing", "private": True})
			result = {"ok": r["ok"], "status": r["status"], "error": r["error"],
				"message_id": (r["data"] or {}).get("id") if r["ok"] else None, "log": r["log"]}

		elif action == "send_customer_message":
			# Customer-facing (goes out on the conversation's channel, e.g. WhatsApp). Only when the
			# setting is on and the customer has not opted out (checked above).
			cid = int(payload.get("conversation_id") or 0)
			content = str(payload.get("content") or "").strip()
			if not cid or not content:
				frappe.throw("conversation_id and content are required")
			# Re-check against Chatwoot itself (payload.phone is only what the ticket says): one GET of the
			# conversation's messages; its meta.contact is the real recipient.
			m = cw(ctx, "GET", "/conversations/" + str(cid) + "/messages", None)
			mdata = (m["data"] or {}) if m["ok"] else {}
			contact = (mdata.get("meta") or {}).get("contact") or {}
			# Real recipient (user-approved 2026-10-19): a Somali mobile OR any full international E.164
			# number — intl() decides (Somali 9 / 0+9 / 252+12 shapes, or +/00 with 8-15 digits). No slicing
			# of longer numbers. "real" keeps the last-9-digit key for the Test numbers compare below.
			full_real = intl(contact.get("phone_number"))
			real = n9(full_real) if full_real else ""
			opted = (contact.get("custom_attributes") or {}).get("opted_out") in [True, 1, "1", "true", "yes"]
			for msg in mdata.get("payload") or []:
				if msg.get("message_type") in [0, "incoming"] and str(msg.get("content") or "").strip().upper() == "JOOJI":
					opted = True
			if not m["ok"]:
				result = {"ok": False, "skipped": True, "log": skip_log(action, payload,
					"Could not read the conversation to check the recipient (HTTP " + str(m["status"]) + ")")}
			elif opted:
				if payload.get("ticket") and frappe.db.exists("HD Ticket", payload.get("ticket")):
					frappe.db.set_value("HD Ticket", payload.get("ticket"), "chatwoot_opted_out", 1, update_modified=False)
				result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "opted out (JOOJI)")}
			elif not real:
				result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Conversation contact has no valid phone number")}
			elif test_keys and real not in test_keys:
				result = {"ok": False, "skipped": True, "log": skip_log(action, payload, "Test mode: conversation contact is not in Test numbers")}
			else:
				r = cw(ctx, "POST", "/conversations/" + str(cid) + "/messages",
					{"content": content, "message_type": "outgoing", "private": False})
				result = {"ok": r["ok"], "status": r["status"], "error": r["error"],
					"message_id": (r["data"] or {}).get("id") if r["ok"] else None, "log": r["log"]}

		elif action == "ensure_conversation":
			# Find (or create) the customer's WhatsApp conversation in the default inbox, keyed like the
			# sadarsms channel does: source_id = 252XXXXXXXXX@s.whatsapp.net. Creating one sends nothing.
			full = intl(payload.get("phone"))
			inbox = int(payload.get("inbox_id") or s.default_inbox_id or 0)
			if not full or not inbox:
				frappe.throw("A valid phone number and an inbox are required")
			key = full[-9:]
			jid = full + "@s.whatsapp.net"
			found = cw(ctx, "GET", "/contacts/search?include_contacts=true&q=" + key, None)
			contact = None
			for c in ((found["data"] or {}).get("payload") or []) if found["ok"] else []:
				if intl(c.get("phone_number")) == full:
					has_inbox = False
					for ci in c.get("contact_inboxes") or []:
						if (ci.get("inbox") or {}).get("id") == inbox:
							has_inbox = True
					if contact is None or has_inbox:
						contact = {"id": c.get("id"), "has_inbox": has_inbox}
			created = []
			if contact is None and found["ok"]:
				newc = {"name": str(payload.get("name") or ("+" + full)), "phone_number": "+" + full}
				if payload.get("company"):
					newc["additional_attributes"] = {"company_name": str(payload.get("company"))}
				r = cw(ctx, "POST", "/contacts", newc)
				cid_new = ((r["data"] or {}).get("payload") or {}).get("contact") or ((r["data"] or {}).get("payload") or {})
				if r["ok"] and cid_new.get("id"):
					contact = {"id": cid_new.get("id"), "has_inbox": False}
					created.append("contact")
			result = {"ok": False, "log": found["log"]}
			if contact:
				if not contact["has_inbox"]:
					r = cw(ctx, "POST", "/contacts/" + str(contact["id"]) + "/contact_inboxes", {"inbox_id": inbox, "source_id": jid})
					if r["ok"]:
						created.append("contact_inbox")
				conv = None
				r = cw(ctx, "GET", "/contacts/" + str(contact["id"]) + "/conversations", None)
				best = 0
				for c in ((r["data"] or {}).get("payload") or []) if r["ok"] else []:
					if c.get("inbox_id") == inbox and (payload.get("any_status") or c.get("status") in ["open", "pending", "snoozed"]) and (c.get("last_activity_at") or 0) >= best:
						best = c.get("last_activity_at") or 0
						conv = c.get("id")
				if conv is None:
					r = cw(ctx, "POST", "/conversations", {"source_id": jid, "inbox_id": inbox, "contact_id": contact["id"], "status": "open"})
					conv = (r["data"] or {}).get("id") if r["ok"] else None
					if conv:
						created.append("conversation")
				result = {"ok": bool(conv), "conversation_id": conv, "contact_id": contact["id"], "created": created,
					"new_conversation": "conversation" in created, "log": r["log"]}

		elif action == "send_agent_message":
			# Staff WhatsApp (assignment brief). One conversation per agent in the default inbox is reused and left
			# resolved afterwards, so staff messages do not crowd the agents' Open list.
			got = (run_script("Chatwoot API", action="ensure_conversation", internal_key=s.get_password("internal_key", raise_exception=False),
				payload={"phone": payload.get("phone"), "name": payload.get("name"), "ticket": payload.get("ticket"), "any_status": 1}) or {}).get("chatwoot_result") or {}
			cid = got.get("conversation_id")
			if not cid:
				result = {"ok": False, "error": "No conversation for the agent", "log": got.get("log")}
			else:
				ctx["conversation_id"] = cid
				r = cw(ctx, "POST", "/conversations/" + str(cid) + "/messages",
					{"content": str(payload.get("content") or "").strip(), "message_type": "outgoing", "private": False})
				if r["ok"]:
					cw(ctx, "POST", "/conversations/" + str(cid) + "/toggle_status", {"status": "resolved"})
				result = {"ok": r["ok"], "status": r["status"], "error": r["error"], "conversation_id": cid, "log": r["log"]}

		elif action == "set_conversation_label":
			cid = int(payload.get("conversation_id") or 0)
			add = [str(x) for x in (payload.get("add") or [])]
			remove = [str(x) for x in (payload.get("remove") or [])]
			g = cw(ctx, "GET", "/conversations/" + str(cid) + "/labels", None)
			if not g["ok"]:
				result = {"ok": False, "status": g["status"], "error": g["error"], "log": g["log"]}
			else:
				# Loops, not comprehensions: script-level names are not visible inside a comprehension here.
				labels = []
				for x in (g["data"] or {}).get("payload") or []:
					if x not in remove:
						labels.append(x)
				for x in add:
					if x not in labels:
						labels.append(x)
				r = cw(ctx, "POST", "/conversations/" + str(cid) + "/labels", {"labels": labels})
				result = {"ok": r["ok"], "status": r["status"], "error": r["error"], "labels": labels, "log": r["log"]}

		elif action == "list_labeled_conversations":
			# Open conversations carrying the ticket label -> display ids (25 per page, max 20 pages).
			raw = str(s.ticket_label or "ticket").strip()
			label = ""
			for ch in raw:
				if ch.isalnum() or ch in "-_":
					label = label + ch
			ids = []
			page = 1
			r = {"ok": True, "status": 0, "error": None, "log": None}
			while page <= 20:
				r = cw(ctx, "GET", "/conversations?status=open&assignee_type=all&labels%5B%5D=" + label + "&page=" + str(page), None)
				if not r["ok"]:
					break
				rows = ((r["data"] or {}).get("data") or {}).get("payload") or []
				for c in rows:
					if c.get("id") and c.get("id") not in ids:
						ids.append(c.get("id"))
				if len(rows) < 25:
					break
				page = page + 1
			result = {"ok": r["ok"], "status": r["status"], "error": r["error"], "ids": ids, "pages": page, "log": r["log"]}

		elif action == "setup_webhook":
			# Our ONE account webhook (inbox_id empty) -> <helpdesk_url>/api/method/chatwoot_webhook_<webhook_key>.
			# The key is the method name: Frappe drops ?query args when the body is JSON, and safe_exec cannot read headers.
			# payload.active false: delete only the webhook whose id we stored. Inbox webhooks are never touched.
			# The key and the URL are never returned or logged (cw() redacts them).
			# Order: (1) Chatwoot accepts the new URL, (2) Server Script "Chatwoot Webhook".api_method, (3) Settings.
			# If (2)/(3) fail, Chatwoot is pointed back at the old URL, so the live state stays consistent.
			# Prefer helpdesk_url (portal.yool.tech); else the site URL; only our two hosts are accepted.
			site = str(s.helpdesk_url or "").strip().rstrip("/")
			if site not in ["https://my.yool.tech", "https://portal.yool.tech"]:
				try:
					site = str(frappe.utils.get_url() or "").rstrip("/")
				except Exception:
					site = ""
			if site not in ["https://my.yool.tech", "https://portal.yool.tech"]:
				site = "https://my.yool.tech"
			hook_id = str(s.chatwoot_webhook_id or "").strip()
			subs = ["conversation_updated", "conversation_created", "conversation_status_changed"]
			prefix = site + "/api/method/chatwoot_webhook_"
			if payload.get("active") in [False, 0, "0", "false", "False"]:
				if not hook_id:
					result = {"ok": True, "active": False, "note": "No stored webhook id; nothing deleted"}
				else:
					r = cw(ctx, "DELETE", "/webhooks/" + str(int(hook_id)), None)
					if r["ok"] or r["status"] == 404:
						frappe.db.set_value("Chatwoot Settings", "Chatwoot Settings", "chatwoot_webhook_id", "")
					result = {"ok": r["ok"] or r["status"] == 404, "status": r["status"], "error": r["error"],
						"active": False, "webhook_id": None, "log": r["log"]}
			else:
				# Fail early, before touching Chatwoot, if the webhook script cannot be read.
				script = frappe.get_doc("Server Script", "Chatwoot Webhook")
				old_key = s.get_password("webhook_key", raise_exception=False) or ""
				key = old_key
				rotated = False
				if len(key) < 48 or payload.get("rotate"):
					key = frappe.utils.generate_hash(length=56)
					if len(key) < 48:
						key = key + frappe.utils.generate_hash(length=56)
					rotated = True
				ctx["secrets"] = ctx["secrets"] + [key, old_key]
				body = {"url": prefix + key, "subscriptions": subs}
				if not hook_id:
					# Adopt an existing account webhook of ours (old or new URL form) instead of a 422 "url taken".
					g = cw(ctx, "GET", "/webhooks", None)
					hooks = (((g["data"] or {}).get("payload") or {}).get("webhooks") or []) if g["ok"] else []
					for h in hooks:
						if not h.get("inbox_id") and str(h.get("url") or "").startswith(site + "/api/method/chatwoot_webhook"):
							hook_id = str(h.get("id"))
				r = None
				if hook_id:
					r = cw(ctx, "PATCH", "/webhooks/" + str(int(hook_id)), body)
					if not r["ok"] and r["status"] == 404:
						hook_id = ""
				if not hook_id:
					r = cw(ctx, "POST", "/webhooks", body)
					if r["ok"]:
						d = r["data"] or {}
						w = (d.get("payload") or {}).get("webhook") or d.get("payload") or d
						hook_id = str(w.get("id") or "")
				note = None
				ok = bool(r["ok"] and hook_id)
				if ok:
					try:
						if script.api_method != "chatwoot_webhook_" + key:
							script.api_method = "chatwoot_webhook_" + key
							script.save(ignore_permissions=True)
						s.webhook_key = key
						s.chatwoot_webhook_id = hook_id
						s.save(ignore_permissions=True)
					except Exception as e:
						# Point Chatwoot back at the old URL, then throw: the whole request (api_method, settings,
						# log rows) rolls back, so Frappe and Chatwoot never disagree about the key.
						note = "Saving the new key failed: " + str(e)[:300]
						if old_key and rotated:
							back = cw(ctx, "PATCH", "/webhooks/" + str(int(hook_id)), {"url": prefix + old_key, "subscriptions": subs})
							note = note + ("; Chatwoot pointed back to the old URL" if back["ok"] else "; revert FAILED, run setup_webhook again")
						elif not old_key:
							note = note + "; Chatwoot now calls a method that does not exist, run setup_webhook again"
						for sec in [key, old_key]:
							if sec:
								note = note.replace(sec, "***")
						frappe.throw(note)
				result = {"ok": ok, "status": r["status"], "error": r["error"], "note": note, "active": True,
					"webhook_id": hook_id or None, "url": prefix + "***", "subscriptions": subs,
					"rotated": rotated, "log": r["log"]}

# API scripts return their frappe.flags: HTTP callers get {"message": {"chatwoot_result": ...}}.
frappe.flags.chatwoot_result = result

# Server Script — "Chatwoot Inbound"
# Script Type: API | API Method: chatwoot_inbound | Allow Guest: No
#
# The one door in (Chatwoot -> Helpdesk). Only the Supabase bridge calls it, with the API key of
# Chatwoot Settings.bridge_user; the bridge has already checked the Chatwoot HMAC signature and
# forwards {delivery_id, event, signature_ok, reason?}. System Managers may call it to test.
# Every call writes one Inbound Chatwoot Sync Log row; its unique dedupe_key means the same
# delivery is never processed twice.
#
# conversation_updated with the ticket label -> one HD Ticket per conversation (unique
#   chatwoot_conversation_id), then a private note with the link back in Chatwoot.
# message_created "JOOJI" from the customer -> the linked ticket is marked opted out.
# All Chatwoot reads/writes go through the outbound door: run_script("Chatwoot API", ...).


def esc(text):
	return str(text or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>")


def caller_phone(raw):
	# Same rule as the HD Ticket Caller Validation script: +252 + 9 digits, or nothing.
	cleaned = "".join([c for c in str(raw or "").strip() if c not in " -.()"])
	digits = cleaned[1:] if cleaned.startswith("+") else (cleaned[2:] if cleaned.startswith("00") else cleaned)
	local = ""
	if digits.startswith("252") and len(digits) == 12:
		local = digits[3:]
	elif digits.startswith("0") and len(digits) == 10:
		local = digits[1:]
	elif len(digits) == 9:
		local = digits
	if not digits.isdigit() or not local.isdigit() or len(local) != 9 or local[0] == "0":
		return None
	return "+252" + local


def n9(phone):
	# The join key: digits only, no leading zeros, 252 prefix, compared on the last 9 digits.
	d = "".join([c for c in str(phone or "") if c.isdigit()]).lstrip("0")
	if not d:
		return ""
	if not d.startswith("252"):
		d = "252" + d
	return d[-9:]


def door(action, payload):
	flags = run_script("Chatwoot API", action=action, payload=payload)
	return (flags or {}).get("chatwoot_result") or {}


def fmt_ts(ts):
	# Chatwoot sends Unix seconds (UTC); shown in Mogadishu time (UTC+3, no DST).
	try:
		epoch = frappe.utils.get_datetime("1970-01-01 00:00:00")
		return frappe.utils.add_to_date(epoch, seconds=int(ts) + 3 * 3600).strftime("%d-%m-%Y %H:%M")
	except Exception:
		return ""


def label_names(labels):
	out = []
	for x in labels or []:
		out.append(x.get("title") if isinstance(x, dict) else str(x))
	return out


args = frappe.form_dict
s = frappe.get_doc("Chatwoot Settings")
user = frappe.session.user
admin = user == "Administrator" or bool(frappe.get_all(
	"Has Role", filters={"parent": user, "parenttype": "User", "role": "System Manager"}, pluck="role"))
if not admin and (not s.bridge_user or user != s.bridge_user):
	frappe.throw("Not permitted", frappe.PermissionError)

event = args.get("event") or {}
if isinstance(event, str):
	event = json.loads(event) if event.strip() else {}
name = str(event.get("event") or args.get("event_name") or "unknown")
delivery = str(args.get("delivery_id") or "").strip()
# Webhook "id" of a conversation is its display id, the one used in Chatwoot URLs and the API.
if name.startswith("conversation_"):
	conv_id = event.get("id")
else:
	conv_id = (event.get("conversation") or {}).get("display_id") or (event.get("conversation") or {}).get("id")
dedupe = ("cw:" + delivery) if delivery else ("cw:" + name + ":" + str(conv_id or "") + ":" + str(event.get("id") or "") + ":" + str(event.get("updated_at") or event.get("created_at") or ""))

log = frappe.get_doc({
	"doctype": "Chatwoot Sync Log",
	"direction": "Inbound",
	"event": name,
	"status": "Success",
	"chatwoot_conversation_id": conv_id,
	"method": "POST",
	"path": "/api/method/chatwoot_inbound",
	"request": json.dumps({"delivery_id": delivery, "signature_ok": args.get("signature_ok"), "event": event}, indent=1, default=str)[:60000],
})
result = {"ok": True, "event": name}

if not args.get("signature_ok"):
	# The bridge rejected the HMAC; Frappe only records it.
	log.status = "Rejected"
	log.error = str(args.get("reason") or "Invalid or missing signature")[:500]
	log.insert(ignore_permissions=True)
	result = {"ok": False, "rejected": True, "log": log.name}
elif frappe.db.exists("Chatwoot Sync Log", {"dedupe_key": dedupe}):
	log.status = "Duplicate"
	log.error = "Already processed: " + dedupe
	log.insert(ignore_permissions=True)
	result = {"ok": True, "duplicate": True, "log": log.name}
else:
	log.dedupe_key = dedupe
	log.insert(ignore_permissions=True)
	note = None
	if not s.enabled:
		log.status = "Skipped"
		note = "Integration is disabled in Chatwoot Settings"

	elif name == "conversation_updated" or name == "conversation_created":
		label = (s.ticket_label or "ticket").strip()
		labels = label_names(event.get("labels"))
		existing = frappe.db.get_value("HD Ticket", {"chatwoot_conversation_id": str(conv_id)}, ["name", "status"], as_dict=True) if conv_id else None
		if not conv_id or label not in labels:
			log.status = "Skipped"
			note = "No '" + label + "' label"
		elif existing:
			# Idempotent: one ticket per conversation, whatever happens to the label.
			log.status = "Skipped"
			log.reference_ticket = existing.name
			note = "Ticket #" + str(existing.name) + " already exists (" + str(existing.status) + ")"
		else:
			# Read the conversation from Chatwoot itself (the webhook body is only a trigger).
			got = door("get_conversation", {"conversation_id": conv_id, "with_messages": True})
			if not got.get("ok"):
				log.status = "Failed"
				note = "Could not read conversation from Chatwoot (HTTP " + str(got.get("status")) + ")"
			else:
				c = got.get("conversation") or {}
				meta = c.get("meta") or {}
				sender = meta.get("sender") or {}
				assignee = meta.get("assignee") or {}
				msgs = []
				for m in got.get("messages") or []:
					if m.get("message_type") in [0, 1, "incoming", "outgoing"] and not m.get("private") and (m.get("content") or "").strip():
						msgs.append(m)
				first_in = None
				opted_out = False
				for m in msgs:
					incoming = m.get("message_type") in [0, "incoming"]
					if incoming and first_in is None:
						first_in = m
					if incoming and (m.get("content") or "").strip().upper() == "JOOJI":
						opted_out = True
				ca = sender.get("custom_attributes") or {}
				if ca.get("opted_out") in [True, 1, "true", "yes"]:
					opted_out = True

				subject = " ".join(str((first_in or {}).get("content") or "").split())
				subject = (subject[:137] + "...") if len(subject) > 140 else subject
				if not subject:
					subject = "Chatwoot #" + str(conv_id)

				base = (s.base_url or "").rstrip("/")
				conv_url = base + "/app/accounts/" + str(s.account_id) + "/conversations/" + str(conv_id)
				lines = []
				for m in msgs[-10:]:
					who = (m.get("sender") or {}).get("name") or ("Customer" if m.get("message_type") in [0, "incoming"] else "Agent")
					when = fmt_ts(m.get("created_at"))
					lines.append("<p><b>" + esc(who) + "</b>" + (" · " + when if when else "") + "<br>" + esc(m.get("content")) + "</p>")
				description = "".join(lines) + '<p><a href="' + conv_url + '">Open in Chatwoot #' + str(conv_id) + "</a></p>"

				# Company: only when the phone points to exactly one Customer (last 9 digits).
				key = n9(sender.get("phone_number"))
				customer = None
				candidates = []
				if len(key) == 9:
					rows = frappe.db.sql(
						"""select distinct dl.link_name from `tabContact` c
						join `tabDynamic Link` dl on dl.parent = c.name and dl.parenttype = 'Contact' and dl.link_doctype = 'Customer'
						left join `tabContact Phone` cp on cp.parent = c.name
						where right(regexp_replace(coalesce(cp.phone, ''), '[^0-9]', ''), 9) = %(k)s
							or right(regexp_replace(coalesce(c.mobile_no, ''), '[^0-9]', ''), 9) = %(k)s
							or right(regexp_replace(coalesce(c.phone, ''), '[^0-9]', ''), 9) = %(k)s
						union
						select name from `tabCustomer` where right(regexp_replace(coalesce(mobile_no, ''), '[^0-9]', ''), 9) = %(k)s""",
						{"k": key},
					)
					for r in rows:
						candidates.append(r[0])
					if len(candidates) == 1:
						customer = candidates[0]

				# Assignee: mapped HD Agent by Chatwoot agent id or email; otherwise Unassigned.
				hd_agent = None
				for row in s.agent_map or []:
					if row.hd_agent and ((assignee.get("id") and row.chatwoot_agent_id == assignee.get("id")) or
						(assignee.get("email") and (row.chatwoot_email or "").lower() == (assignee.get("email") or "").lower())):
						hd_agent = row.hd_agent

				ticket = frappe.get_doc({
					"doctype": "HD Ticket",
					"subject": subject,
					"description": description,
					"caller_name": (sender.get("name") or "").strip() or None,
					"caller_phone": caller_phone(sender.get("phone_number")),
					"erp_customer": customer,
					"source": "Chatwoot",
					"chatwoot_conversation_id": str(conv_id),
					"chatwoot_contact_id": str(sender.get("id") or "") or None,
					"chatwoot_inbox": str(c.get("inbox_id") or ""),
					"chatwoot_opted_out": 1 if opted_out else 0,
				})
				try:
					ticket.insert(ignore_permissions=True)
				except frappe.UniqueValidationError:
					ticket = None
				except frappe.DuplicateEntryError:
					ticket = None
				if ticket is None:
					# Two deliveries raced; the other one created it.
					log.status = "Duplicate"
					log.reference_ticket = frappe.db.get_value("HD Ticket", {"chatwoot_conversation_id": str(conv_id)}, "name")
					note = "Ticket already created by a parallel delivery"
				else:
					log.reference_ticket = ticket.name
					details = ["Ticket #" + str(ticket.name) + " created"]
					details.append("Company: " + (customer or ("ambiguous: " + ", ".join(candidates[:5]) if candidates else "no match")))
					if hd_agent:
						try:
							ticket.assign_agent(hd_agent)
							details.append("Assigned: " + hd_agent)
						except Exception as e:
							details.append("Assign failed: " + str(e)[:200])
					else:
						details.append("Unassigned")
					if opted_out:
						details.append("Opted out (JOOJI)")
					link = (s.helpdesk_url or "https://my.yool.tech").rstrip("/") + "/helpdesk/tickets/" + str(ticket.name)
					sent = door("add_private_note", {"conversation_id": conv_id, "ticket": ticket.name,
						"content": "🎫 Ticket #" + str(ticket.name) + " created: " + link})
					details.append("Private note: " + ("sent" if sent.get("ok") else "FAILED, see " + str(sent.get("log"))))
					note = "; ".join(details)
					result["ticket"] = ticket.name

	elif name == "message_created":
		# JOOJI from the customer: never message them automatically.
		msg_type = event.get("message_type")
		text = (event.get("content") or "").strip().upper()
		if msg_type in [0, "incoming"] and text == "JOOJI" and conv_id:
			t = frappe.db.get_value("HD Ticket", {"chatwoot_conversation_id": str(conv_id)}, "name")
			if t:
				frappe.db.set_value("HD Ticket", t, "chatwoot_opted_out", 1, update_modified=False)
				log.reference_ticket = t
				note = "Opt-out recorded on ticket #" + str(t)
			else:
				note = "JOOJI received; no linked ticket"
		else:
			log.status = "Skipped"
			note = "Not a JOOJI message"
	else:
		log.status = "Skipped"
		note = "Event not handled"

	log.response = json.dumps({"result": note}, default=str)
	if log.status == "Failed":
		log.error = note
	log.save(ignore_permissions=True)
	result["status"] = log.status
	result["note"] = note
	result["log"] = log.name

frappe.flags.chatwoot_inbound = result

# Server Script — "Chatwoot Settings Team Numbers"
# Script Type: DocType Event | Reference Doctype: Chatwoot Settings | Event: Before Save
#
# Sales-alert team numbers (Custom Fields on Chatwoot Settings; edited in the Kanban "⚙ Team numbers / Numbarrada
# kooxaha" modal by Agent Manager / System Manager, or here in the Desk form):
#   sales_alert_tech_phone  "Numberka Kooxda Technical (WhatsApp)" - receives the "HD Ticket Sales Alert" brief
#   sales_alert_sales_phone "Numberka Kooxda Sales"                - shown inside that brief
# Same rule as "HD Ticket Caller Validation": Somali formats -> +252XXXXXXXXX; any other full international number
# (+ / 00 country code, 8-15 digits) -> +<digits>; empty is allowed (empty Technical number = no alert);
# anything else is rejected.


def team_phone(raw, label):
	raw = str(raw or "").strip()
	if not raw:
		return ""
	cleaned = "".join([c for c in raw if c not in " -.()"])
	if cleaned.startswith("+"):
		digits = cleaned[1:]
	elif cleaned.startswith("00"):
		digits = cleaned[2:]
	else:
		digits = cleaned
	local = ""
	if digits.startswith("252") and len(digits) == 12:
		local = digits[3:]
	elif digits.startswith("0") and len(digits) == 10:
		local = digits[1:]
	elif len(digits) == 9:
		local = digits
	if digits.isdigit() and len(local) == 9 and local.isdigit() and local[0] != "0":
		return "+252" + local
	if (cleaned.startswith("+") or cleaned.startswith("00")) and digits.isdigit() and 8 <= len(digits) <= 15 and digits[0] != "0":
		return "+" + digits
	frappe.throw(
		label + ": geli number Soomaali ah (06.../+252...) ama mid caalami ah (+country code).  /  "
		+ label + ": enter a Somali number or a full international number (+country code).",
		title="Invalid team number",
	)


doc.sales_alert_tech_phone = team_phone(doc.get("sales_alert_tech_phone"), "Numberka Kooxda Technical (WhatsApp)")
doc.sales_alert_sales_phone = team_phone(doc.get("sales_alert_sales_phone"), "Numberka Kooxda Sales")

# Server Script — "Chatwoot Webhook"
# Script Type: API | API Method: chatwoot_webhook_<webhook_key> (set by the door's setup_webhook) | Allow Guest: Yes
#
# The one door in (Chatwoot -> Helpdesk), replaces the bridge-based "Chatwoot Inbound".
#   HTTP:     Chatwoot account webhook -> POST /api/method/chatwoot_webhook_<Chatwoot Settings.webhook_key>
#             (runs as Guest). The key is in the method name because Frappe drops ?query args when the body is
#             JSON and safe_exec cannot read headers. form_dict.cmd must equal "chatwoot_webhook_" + the stored key.
#             Wrong keys never get here (Frappe: method not found); keyless calls hit the decoy "Chatwoot Webhook Old URL".
#   Internal: run_script("Chatwoot Webhook", conversation_id=..., source="poll") from "Chatwoot Poll"
#             (scheduler, runs as Administrator; no key). HTTP = form_dict.cmd starts with chatwoot_webhook, or the user is Guest.
# Order: rate limit -> key -> enabled -> event filter -> dedupe -> ticket exists? -> hint has label? -> fetch.
# The payload is only a hint: the ticket is built ONLY from the conversation re-read through the outbound door.
# Every call writes one Inbound Chatwoot Sync Log row (the key, cmd and the request URL are never stored).
# Result in frappe.flags.chatwoot_webhook (HTTP callers get {"message": {"chatwoot_webhook": ...}}).

RAISED_BY_FALLBACK = "chatwoot@yool.tech"
RATE_LIMIT = 120  # Inbound rows per 60 s


def esc(text):
	return str(text or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>")


def caller_phone(raw):
	# Same rule as the HD Ticket Caller Validation script: +252 + 9 digits, or nothing.
	cleaned = "".join([c for c in str(raw or "").strip() if c not in " -.()"])
	digits = cleaned[1:] if cleaned.startswith("+") else (cleaned[2:] if cleaned.startswith("00") else cleaned)
	local = ""
	if digits.startswith("252") and len(digits) == 12:
		local = digits[3:]
	elif digits.startswith("0") and len(digits) == 10:
		local = digits[1:]
	elif len(digits) == 9:
		local = digits
	if not digits.isdigit() or not local.isdigit() or len(local) != 9 or local[0] == "0":
		return None
	return "+252" + local


def n9(phone):
	# The join key: digits only, no leading zeros, 252 prefix, compared on the last 9 digits.
	d = "".join([c for c in str(phone or "") if c.isdigit()]).lstrip("0")
	if not d:
		return ""
	if not d.startswith("252"):
		d = "252" + d
	return d[-9:]


def door(action, payload, wkey):
	# wkey: the webhook key again, so the door accepts this Guest call (None in poll mode = Administrator).
	flags = run_script("Chatwoot API", action=action, payload=payload, webhook_key=wkey)
	return (flags or {}).get("chatwoot_result") or {}


def fmt_ts(ts):
	# Chatwoot sends Unix seconds (UTC); shown in Mogadishu time (UTC+3, no DST).
	try:
		epoch = frappe.utils.get_datetime("1970-01-01 00:00:00")
		v = str(frappe.utils.add_to_date(epoch, seconds=int(ts) + 3 * 3600))  # strftime is not available here
		return v[8:10] + "-" + v[5:7] + "-" + v[0:4] + " " + v[11:16]
	except Exception:
		return ""


def label_names(labels):
	out = []
	for x in labels or []:
		out.append(x.get("title") if isinstance(x, dict) else str(x))
	return out


def plain_email(v):
	v = str(v or "").strip().lower()
	at = v.find("@")
	if at > 0 and "." in v[at:] and " " not in v and "<" not in v and len(v) <= 140:
		return v
	return None


def new_log(status, event, conv, error, request):
	return frappe.get_doc({
		"doctype": "Chatwoot Sync Log",
		"direction": "Inbound",
		"event": event,
		"status": status,
		"chatwoot_conversation_id": conv,
		"method": "POST",
		"path": "/api/method/chatwoot_webhook",
		"request": request,
		"error": error,
	}).insert(ignore_permissions=True).name


args = frappe.form_dict
s = frappe.get_doc("Chatwoot Settings")
user = frappe.session.user
# frappe.request does not exist in safe_exec; form_dict.cmd is the /api/method/<cmd> really running.
# Guest is always treated as HTTP (key required), whatever the route (/api/v2 leaves cmd empty).
cmd = str(args.get("cmd") or "")
http = cmd.startswith("chatwoot_webhook") or user == "Guest"
result = {"ok": False}
stop = False

if http:
	since = frappe.utils.add_to_date(frappe.utils.now_datetime(), seconds=-60)
	recent = frappe.db.count("Chatwoot Sync Log", {"direction": "Inbound", "creation": [">", since]})
	# At most one Rejected row per minute (any reason), so a flood can neither fill the table nor push the
	# rate-limit count up and block real deliveries.
	quiet = bool(frappe.db.exists("Chatwoot Sync Log", {"direction": "Inbound", "status": "Rejected", "creation": [">", since]}))
	if recent > RATE_LIMIT:
		if not quiet:
			new_log("Rejected", str(args.get("event") or "unknown")[:140], None, "rate limit", None)
		result = {"ok": False, "rejected": True}
		stop = True
	else:
		wkey = s.get_password("webhook_key", raise_exception=False) or ""
		if len(wkey) < 32 or cmd != "chatwoot_webhook_" + wkey:
			if not quiet:
				new_log("Rejected", str(args.get("event") or "unknown")[:140], None,
					"No webhook key configured" if len(wkey) < 32 else "Key does not match", None)
			result = {"ok": False, "rejected": True}
			stop = True
else:
	# Internal call (poller). Not reachable over HTTP: that path always takes the key branch above.
	admin = user == "Administrator" or bool(frappe.get_all(
		"Has Role", filters={"parent": user, "parenttype": "User", "role": "System Manager"}, pluck="role"))
	if not admin:
		frappe.throw("Not permitted", frappe.PermissionError)
	wkey = None

if not stop:
	if http:
		name = str(args.get("event") or "unknown")[:140]
		conv_id = args.get("id")
		hint_labels = args.get("labels")
	else:
		name = "poll"
		conv_id = args.get("conversation_id")
		hint_labels = None
	try:
		conv_id = int(conv_id or 0) or None
	except Exception:
		conv_id = None
	handled = name in ["conversation_updated", "conversation_created", "conversation_status_changed", "poll"]

	if not s.enabled:
		result = {"ok": True, "status": "Skipped", "log": new_log("Skipped", name, conv_id, "Integration is disabled in Chatwoot Settings", None)}
	elif not handled:
		# Small row, no payload, no Chatwoot call.
		result = {"ok": True, "status": "Skipped", "log": new_log("Skipped", name, None, "Event not handled", None)}
	else:
		# What we keep of the request: the body only, never "key"/"cmd" (loop: no comprehensions over script locals).
		kept = {}
		for k in args:
			if k not in ["key", "cmd", "webhook_key", "internal_key", "action", "payload"]:
				kept[k] = args.get(k)
		log = frappe.get_doc({
			"doctype": "Chatwoot Sync Log",
			"direction": "Inbound",
			"event": name,
			"status": "Success",
			"chatwoot_conversation_id": conv_id,
			"method": "POST" if http else None,
			"path": "/api/method/chatwoot_webhook",
			"request": json.dumps(kept, indent=1, default=str)[:20000],
		})
		dedupe = None
		if http:
			stamp = args.get("updated_at") or args.get("created_at") or args.get("timestamp")
			if stamp:
				dedupe = "cw:" + name + ":" + str(conv_id or "") + ":" + str(stamp)
		dup = False
		if dedupe and frappe.db.exists("Chatwoot Sync Log", {"dedupe_key": dedupe}):
			dup = True
		else:
			log.dedupe_key = dedupe
			try:
				log.insert(ignore_permissions=True)
			except frappe.UniqueValidationError:
				dup = True
			except frappe.DuplicateEntryError:
				dup = True
		if dup:
			result = {"ok": True, "status": "Duplicate", "log": new_log("Duplicate", name, conv_id, "Already processed: " + str(dedupe), None)}
		else:
			note = None
			label = (s.ticket_label or "ticket").strip()
			existing = frappe.db.get_value("HD Ticket", {"chatwoot_conversation_id": str(conv_id)}, ["name", "status"], as_dict=True) if conv_id else None
			if conv_id and not existing:
				# A Helpdesk ticket already linked to this conversation (HD Ticket Chatwoot Link) and still open counts too.
				existing = frappe.db.get_value("HD Ticket", {"chatwoot_reply_conversation": str(conv_id),
					"status": ["not in", ["Resolved", "Closed", "Cancelled"]]}, ["name", "status"], as_dict=True)
			if not conv_id:
				log.status = "Skipped"
				note = "No conversation id"
			elif existing:
				# Idempotent: one ticket per conversation, whatever happens to the label.
				log.status = "Skipped"
				log.reference_ticket = existing.name
				note = "Ticket #" + str(existing.name) + " already exists (" + str(existing.status) + ")"
			elif http and isinstance(hint_labels, list) and label not in label_names(hint_labels):
				log.status = "Skipped"
				note = "No '" + label + "' label (hint)"
			else:
				# Verify by fetch: from here on only Chatwoot's own data counts.
				got = door("get_conversation", {"conversation_id": conv_id, "with_messages": True}, wkey)
				c = got.get("conversation") or {}
				if not got.get("ok"):
					log.status = "Failed"
					note = "Could not read conversation from Chatwoot (HTTP " + str(got.get("status")) + ")"
				elif label not in label_names(c.get("labels")):
					log.status = "Skipped"
					note = "No '" + label + "' label (verified in Chatwoot)"
				else:
					meta = c.get("meta") or {}
					sender = meta.get("sender") or {}
					assignee = meta.get("assignee") or {}
					msgs = []
					for m in got.get("messages") or []:
						if m.get("message_type") in [0, 1, "incoming", "outgoing"] and not m.get("private") and (m.get("content") or "").strip():
							msgs.append(m)
					first_in = None
					opted_out = False
					for m in msgs:
						incoming = m.get("message_type") in [0, "incoming"]
						if incoming and first_in is None:
							first_in = m
						if incoming and (m.get("content") or "").strip().upper() == "JOOJI":
							opted_out = True
					ca = sender.get("custom_attributes") or {}
					if ca.get("opted_out") in [True, 1, "true", "yes"]:
						opted_out = True

					subject = " ".join(str((first_in or {}).get("content") or "").split())
					subject = (subject[:137] + "...") if len(subject) > 140 else subject
					if not subject:
						subject = "Chatwoot #" + str(conv_id)

					base = (s.base_url or "").rstrip("/")
					conv_url = base + "/app/accounts/" + str(s.account_id) + "/conversations/" + str(conv_id)
					lines = []
					for m in msgs[-10:]:
						who = (m.get("sender") or {}).get("name") or ("Customer" if m.get("message_type") in [0, "incoming"] else "Agent")
						when = fmt_ts(m.get("created_at"))
						lines.append("<p><b>" + esc(who) + "</b>" + (" · " + when if when else "") + "<br>" + esc(m.get("content")) + "</p>")
					description = "".join(lines) + '<p><a href="' + conv_url + '">Open in Chatwoot #' + str(conv_id) + "</a></p>"

					# Company: only when the phone points to exactly one Customer (last 9 digits).
					key9 = n9(sender.get("phone_number"))
					customer = None
					candidates = []
					if len(key9) == 9:
						rows = frappe.db.sql(
							"""select distinct dl.link_name from `tabContact` c
							join `tabDynamic Link` dl on dl.parent = c.name and dl.parenttype = 'Contact' and dl.link_doctype = 'Customer'
							left join `tabContact Phone` cp on cp.parent = c.name
							where right(regexp_replace(coalesce(cp.phone, ''), '[^0-9]', ''), 9) = %(k)s
								or right(regexp_replace(coalesce(c.mobile_no, ''), '[^0-9]', ''), 9) = %(k)s
								or right(regexp_replace(coalesce(c.phone, ''), '[^0-9]', ''), 9) = %(k)s
							union
							select name from `tabCustomer` where right(regexp_replace(coalesce(mobile_no, ''), '[^0-9]', ''), 9) = %(k)s""",
							{"k": key9},
						)
						for r in rows:
							candidates.append(r[0])
						if len(candidates) == 1:
							customer = candidates[0]

					# Assignee: mapped HD Agent by Chatwoot agent id or email; otherwise Unassigned.
					hd_agent = None
					for row in s.agent_map or []:
						if row.hd_agent and ((assignee.get("id") and row.chatwoot_agent_id == assignee.get("id")) or
							(assignee.get("email") and (row.chatwoot_email or "").lower() == (assignee.get("email") or "").lower())):
							hd_agent = row.hd_agent

					# Never "Guest" and never the customer: a fixed placeholder address.
					raised_by = RAISED_BY_FALLBACK  # never the customer's email: Helpdesk could email them
					ticket = frappe.get_doc({
						"doctype": "HD Ticket",
						"subject": subject,
						"description": description,
						"raised_by": raised_by,
						"owner": "Administrator",
						"caller_name": (sender.get("name") or "").strip() or None,
						"caller_phone": caller_phone(sender.get("phone_number")),
						"erp_customer": customer,
						"source": "Chatwoot",
						"chatwoot_conversation_id": str(conv_id),
						"chatwoot_contact_id": str(sender.get("id") or "") or None,
						"chatwoot_inbox": str(c.get("inbox_id") or ""),
						"chatwoot_opted_out": 1 if opted_out else 0,
					})
					insert_error = None
					try:
						ticket.insert(ignore_permissions=True)
					except frappe.UniqueValidationError:
						ticket = None
					except frappe.DuplicateEntryError:
						ticket = None
					except Exception as e:
						insert_error = str(e)[:500]
					if insert_error:
						log.status = "Failed"
						note = "Ticket insert failed: " + insert_error
					elif ticket is None:
						# Two deliveries raced; the other one created it.
						log.status = "Duplicate"
						log.reference_ticket = frappe.db.get_value("HD Ticket", {"chatwoot_conversation_id": str(conv_id)}, "name")
						note = "Ticket already created by a parallel delivery"
					else:
						log.reference_ticket = ticket.name
						details = ["Ticket #" + str(ticket.name) + " created", "raised_by: " + raised_by]
						owner_now = frappe.db.get_value("HD Ticket", ticket.name, "owner")
						if owner_now == "Administrator":
							details.append("owner kept: Administrator")
						else:
							# Frappe overwrote it with the session user (Guest); fix it without touching modified.
							frappe.db.set_value("HD Ticket", ticket.name, {"owner": "Administrator", "modified_by": "Administrator"}, update_modified=False)
							details.append("owner was " + str(owner_now) + ", set to Administrator")
						details.append("Company: " + (customer or ("ambiguous: " + ", ".join(candidates[:5]) if candidates else "no match")))
						if hd_agent:
							try:
								ticket.assign_agent(hd_agent)
								details.append("Assigned: " + hd_agent)
							except Exception as e:
								details.append("Assign failed: " + str(e)[:200])
						else:
							details.append("Unassigned")
						if opted_out:
							details.append("Opted out (JOOJI)")
						link = (s.helpdesk_url or "https://portal.yool.tech").rstrip("/") + "/helpdesk/tickets/" + str(ticket.name)
						sent = door("add_private_note", {"conversation_id": conv_id, "ticket": ticket.name,
							"content": "🎫 Ticket #" + str(ticket.name) + " created: " + link}, wkey)
						details.append("Private note: " + ("sent" if sent.get("ok") else "FAILED, see " + str(sent.get("log"))))
						note = "; ".join(details)
						result["ticket"] = ticket.name

			log.response = json.dumps({"result": note}, default=str)
			if log.status == "Failed":
				log.error = note
			log.save(ignore_permissions=True)
			result["ok"] = log.status != "Failed"
			result["status"] = log.status
			result["note"] = note
			result["log"] = log.name

frappe.flags.chatwoot_webhook = result

# Server Script — "HD Ticket Time Spent"
# Script Type: DocType Event | Reference Doctype: HD Ticket | Event: Before Save
#
# time_spent is a Data field holding "h:mm" (e.g. "1:30"). Whatever an agent types is normalized to h:mm:
#   "1:30" -> 1:30, "1h 30m" / "1h" / "45m" / "1.5h" / "90 min" -> as written, a plain number -> minutes.
# Empty or zero -> empty.
# Invalid text is rejected with a plain-text message (Helpdesk toasts show HTML literally).
# Separate from "HD Ticket Caller Validation" on purpose; touches only time_spent.

value = doc.time_spent
if value is None or value == "":
    doc.time_spent = None
elif isinstance(value, (int, float)):
    # A raw number from the API = minutes.
    value = str(value)
if value is not None and value != "":
    text = str(value).strip().lower().replace(" ", "")
    seconds = None
    if text == "" or text == "0":
        seconds = 0
    elif ":" in text:
        parts = text.split(":")
        if len(parts) in (2, 3) and parts[0].isdigit() and parts[1].isdigit():
            seconds = int(parts[0]) * 3600 + int(parts[1]) * 60
            if len(parts) == 3 and parts[2].isdigit():
                seconds = seconds + int(parts[2])
            elif len(parts) == 3:
                seconds = None
    elif "h" in text or "m" in text:
        hours_part = "0"
        minutes_part = "0"
        rest = text.replace("hrs", "h").replace("hr", "h").replace("min", "m")
        if "h" in rest:
            hours_part = rest.split("h")[0] or "0"
            rest = rest.split("h", 1)[1]
        if "m" in rest:
            minutes_part = rest.split("m")[0] or "0"
            rest = rest.split("m", 1)[1]
        ok = rest == "" and hours_part.replace(".", "", 1).isdigit() and minutes_part.isdigit()
        if ok:
            seconds = int(round(float(hours_part) * 3600)) + int(minutes_part) * 60
    elif text.replace(".", "", 1).isdigit():
        seconds = int(round(float(text) * 60))
    if seconds is None:
        frappe.throw(
            "Time Spent sax ma aha. Tusaale: 1:30, 1h 30m ama 45 (daqiiqo).  /  "
            "Invalid Time Spent. Example: 1:30, 1h 30m or 45 (minutes).",
            title="Invalid Time Spent",
        )
    if seconds > 0:
        minutes = int(round(seconds / 60.0))
        mm = str(minutes % 60)
        if len(mm) < 2:
            mm = "0" + mm
        doc.time_spent = str(int(minutes // 60)) + ":" + mm
    else:
        doc.time_spent = None

# Server Script — "Yool Caller Defaults"
# Script Type: API | API Method: yool_caller_defaults | Allow Guest: No
#
# Returns company + caller defaults for the New Ticket forms.
# - Active HD Agent: may pass ?customer=<Customer>; gets that customer's name,
#   primary contact (id + full name) and phone. caller_name is left empty: agents
#   type the caller themselves.
# - Anyone else (portal user): the `customer` argument is ignored; only the
#   caller's own Contact and its single linked Customer are returned.
# Read-only; values are suggestions, the HD Ticket Before Save script enforces.


def normalize_phone(raw):
    cleaned = "".join([c for c in (raw or "").strip() if c not in " -.()"])
    if cleaned.startswith("+"):
        digits = cleaned[1:]
    elif cleaned.startswith("00"):
        digits = cleaned[2:]
    else:
        digits = cleaned
    if digits.startswith("252") and len(digits) == 12:
        local = digits[3:]
    elif digits.startswith("0") and len(digits) == 10:
        local = digits[1:]
    elif len(digits) == 9:
        local = digits
    else:
        local = ""
    if digits.isdigit() and len(local) == 9 and local.isdigit() and local[0] != "0":
        return "+252" + local
    if (cleaned.startswith("+") or cleaned.startswith("00")) and digits.isdigit() and 8 <= len(digits) <= 15 and digits[0] != "0":
        # Any other country's full international number, as the validation script stores it.
        return "+" + digits
    return None


def contact_person(contact):
    # Returns a dict: safe_exec does not allow tuple unpacking.
    person = {"name": None, "phone": None}
    if not contact:
        return person
    c = frappe.db.get_value(
        "Contact", contact, ["full_name", "first_name", "last_name", "mobile_no", "phone"], as_dict=True
    )
    if not c:
        return person
    name = (c.full_name or " ".join([p.strip() for p in [c.first_name or "", c.last_name or ""] if p.strip()])).strip()
    person["name"] = name or None
    person["phone"] = c.mobile_no or c.phone
    return person


user = frappe.session.user
if user == "Guest":
    frappe.throw("Not permitted", title="Not permitted")

is_agent = user == "Administrator" or frappe.db.get_value("HD Agent", user, "is_active") == 1
result = {
    "customer": None,
    "customer_name": None,
    "contact": None,
    "primary_contact_name": None,
    "caller_name": None,
    "caller_phone": None,
}

if is_agent:
    customer = frappe.form_dict.get("customer")
    row = frappe.db.get_value(
        "Customer", customer, ["name", "customer_name", "customer_primary_contact", "mobile_no"], as_dict=True
    ) if customer else None
    if row:
        person = contact_person(row.customer_primary_contact)
        result["customer"] = row.name
        result["customer_name"] = row.customer_name
        result["contact"] = row.customer_primary_contact
        result["primary_contact_name"] = person["name"]
        result["caller_phone"] = normalize_phone(row.mobile_no) or normalize_phone(person["phone"])
else:
    contact = frappe.db.get_value("Contact", {"user": user}, "name") or frappe.db.get_value(
        "Contact", {"email_id": user}, "name"
    )
    if contact:
        links = frappe.db.sql(
            "SELECT DISTINCT link_name FROM `tabDynamic Link`"
            " WHERE parenttype = 'Contact' AND parentfield = 'links'"
            " AND link_doctype = 'Customer' AND parent = %(contact)s",
            {"contact": contact},
        )
        if len(links) == 1:
            company = frappe.db.get_value(
                "Customer", links[0][0], ["customer_name", "customer_primary_contact"], as_dict=True
            )
            if company:
                result["customer"] = links[0][0]
                result["customer_name"] = company.customer_name
                result["primary_contact_name"] = contact_person(company.customer_primary_contact)["name"]
        person = contact_person(contact)
        result["contact"] = contact
        result["caller_name"] = person["name"]
        result["caller_phone"] = normalize_phone(person["phone"])
    if not result["caller_name"]:
        result["caller_name"] = frappe.db.get_value("User", user, "full_name")
    if not result["caller_phone"]:
        result["caller_phone"] = normalize_phone(frappe.db.get_value("User", user, "mobile_no"))

frappe.response["message"] = result
